package com.dailyhelp.service;
import com.dailyhelp.dto.TaskDtos.*; import com.dailyhelp.entity.*; import com.dailyhelp.repository.*; import java.time.LocalDate; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TaskService {private final TaskRepository tasks;private final UserRepository users; public TaskService(TaskRepository tasks,UserRepository users){this.tasks=tasks;this.users=users;}
 @Transactional(readOnly=true) public Page<TaskResponse> list(Long uid,String q,TaskStatus status,TaskPriority priority,String sort,int page,int size){if(page<0)throw new IllegalArgumentException("page must be zero or greater");if(size<1||size>100)throw new IllegalArgumentException("size must be between 1 and 100");Sort order=switch(sort==null?"createdAt":sort){case "dueDate"->Sort.by(Sort.Direction.ASC,"dueDate").and(Sort.by("createdAt").descending());case "priority"->Sort.by(Sort.Direction.DESC,"priority").and(Sort.by("createdAt").descending());case "createdAt"->Sort.by(Sort.Direction.DESC,"createdAt");default->throw new IllegalArgumentException("sort must be createdAt, dueDate, or priority");};return tasks.search(uid,status,priority,(q==null||q.isBlank())?null:q.trim(),PageRequest.of(page,size,order)).map(this::view);}
 @Transactional(readOnly=true) public TaskResponse get(Long uid,Long id){return view(owned(uid,id));}
 @Transactional public TaskResponse create(Long uid,TaskRequest r){AppUser owner=users.findById(uid).orElseThrow(()->new NoSuchElementException());return view(tasks.save(new Task(owner,r.title().trim(),r.description(),r.dueDate(),r.priority(),r.status())));}
 @Transactional public TaskResponse update(Long uid,Long id,TaskRequest r){Task t=owned(uid,id);t.update(r.title().trim(),r.description(),r.dueDate(),r.priority(),r.status());return view(t);}
 @Transactional public TaskResponse status(Long uid,Long id,TaskStatus status){Task t=owned(uid,id);t.setStatus(status);return view(t);}
 @Transactional public void delete(Long uid,Long id){tasks.delete(owned(uid,id));}
 @Transactional(readOnly=true) public DashboardResponse dashboard(Long uid){long total=tasks.countByOwnerId(uid),pending=tasks.countByOwnerIdAndStatus(uid,TaskStatus.PENDING),progress=tasks.countByOwnerIdAndStatus(uid,TaskStatus.IN_PROGRESS),done=tasks.countByOwnerIdAndStatus(uid,TaskStatus.COMPLETED),overdue=tasks.countByOwnerIdAndDueDateBeforeAndStatusNot(uid,LocalDate.now(),TaskStatus.COMPLETED);return new DashboardResponse(total,pending,progress,done,overdue,total==0?0.0:Math.round(done*1000.0/total)/10.0,tasks.findTop5ByOwnerIdOrderByCreatedAtDesc(uid).stream().map(this::view).toList(),tasks.findTop5ByOwnerIdAndStatusNotAndDueDateGreaterThanEqualOrderByDueDateAsc(uid,TaskStatus.COMPLETED,LocalDate.now()).stream().map(this::view).toList());}
 private Task owned(Long uid,Long id){return tasks.findByIdAndOwnerId(id,uid).orElseThrow(NoSuchElementException::new);} private TaskResponse view(Task t){return new TaskResponse(t.getId(),t.getTitle(),t.getDescription(),t.getDueDate(),t.getPriority(),t.getStatus(),t.getCreatedAt(),t.getUpdatedAt());}}